/**  Class of a status code as the UI sees it (serialized in camelCase). */
export type StatusClassView = 
/**  `1xx` */
"informational" | 
/**  `2xx` */
"success" | 
/**  `3xx` */
"redirection" | 
/**  `4xx` */
"clientError" | 
/**  `5xx` */
"serverError" | 
/**  `6xx`–`9xx` */
"nonstandard";

/**  The result of one `test(…)` of a script. */
export type TestResultView = TestResultView_Serialize | TestResultView_Deserialize;

/**  The result of one `test(…)` of a script. */
export type TestResultView_Deserialize = {
	/**  The test's name. */
	name: string,
	/**  Whether every check in it held. */
	passed: boolean,
	/**  Why it failed (technical, from the script). */
	message?: string | null,
};

/**  The result of one `test(…)` of a script. */
export type TestResultView_Serialize = {
	/**  The test's name. */
	name: string,
	/**  Whether every check in it held. */
	passed: boolean,
	/**  Why it failed (technical, from the script). */
	message: string | null,
};

/**  Redirects, time limit and cookies of a request, folder or collection. */
export type TransportDraft = TransportDraft_Serialize | TransportDraft_Deserialize;

/**  Redirects, time limit and cookies of a request, folder or collection. */
export type TransportDraft_Deserialize = {
	/**  Redirects. */
	redirects?: RedirectsView,
	/**  Time limit in seconds; `null` inherits. */
	timeoutSeconds?: number | null,
	/**  The cookie jar. */
	cookies?: CookiesView,
};

/**  Redirects, time limit and cookies of a request, folder or collection. */
export type TransportDraft_Serialize = {
	/**  Redirects. */
	redirects: RedirectsView,
	/**  Time limit in seconds; `null` inherits. */
	timeoutSeconds: number | null,
	/**  The cookie jar. */
	cookies: CookiesView,
};

